private void loadTable() {

    DefaultTableModel model = (DefaultTableModel) tblProducts.getModel();
    model.setRowCount(0);

    for (Product p : productService.getAllProducts()) {
        model.addRow(new Object[]{
            p.getId(),
            p.getBrand(),
            p.getModel(),
            p.getCategory(),
            p.getSpecifications(),
            p.getPrice()
        });
    }
}
